LAYER
    INCLUDE "config/database.map"
    DATA "geom from (select g.id, r.rainfall_mm, g.cell as geom from wrf.grid_01dd g join wrf.get_total_rainfall_tiles('%time%') r on g.id = r.id where r.rainfall_mm > 1 and exists (select 1 from gha.admin0 a where a.geom && g.cell and ST_Intersects(g.cell, a.geom))) as subq using unique id using srid=4326"
    MASK "gha_admin_extent_mask"
    INCLUDE "shared/common-layer-properties.map"
    INCLUDE "classifications/wrf-rainfall.classes.map"
    METADATA
        "wms_title" "WRF Daily Rainfall"
        "wms_abstract" "Weekly total rainfall from WRF model (mm)"
        INCLUDE "shared/wms-layer-metadata.map"
    END
    NAME "wrf_daily_rainfall"
    VALIDATION
        "time" "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
        "default_time" "2026-02-17"
    END
END
